"use client";

import { motion } from "motion/react";

export function RevealCardTailwind({ title = "Reveal Card", body = "A spring-driven overlay slides in on hover or focus." }) {
  return (
    <motion.article
      tabIndex={0}
      initial="rest"
      animate="rest"
      whileHover="open"
      whileFocus="open"
      className="relative h-64 w-72 overflow-hidden rounded-2xl border border-zinc-800 bg-zinc-900 text-zinc-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[3px] focus-visible:outline-zinc-200"
    >
      <div aria-hidden className="flex h-full items-center justify-center text-2xl font-bold">{title}</div>
      <motion.div
        variants={{ rest: { y: "100%" }, open: { y: 0 } }}
        transition={{ type: "spring", stiffness: 300, damping: 30 }}
        className="absolute inset-0 flex flex-col justify-end gap-1 bg-sky-400 p-6 text-zinc-950"
      >
        <h3 className="text-xl font-bold">{title}</h3>
        <p className="text-sm opacity-85">{body}</p>
      </motion.div>
    </motion.article>
  );
}
